 private void startSearch(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);query.clearFocus();String q=query.getText().toString().trim();search.setEnabled(false);status.setText("Searching YouTube…");page="search";worker.execute(()->{try{List<Track> found=MusicRepository.search(this,q);runOnUiThread(()->{if(isDestroyed())return;queue=found;showResults(found);status.setText(found.isEmpty()?"No results. Try another search.":found.size()+" results · preview or download");});}catch(Exception e){runOnUiThread(()->status.setText("Search failed. "+DownloadErrors.friendly(e.getMessage())));}finally{runOnUiThread(()->search.setEnabled(true));}});}
